window.RI1_UNITS = {"2":{"unit":2,"code":"RI1-U02","title":"TRAVEL & ADVENTURE","startNumber":20,"endNumber":49,"entries":[{"number":20,"term":"adventure (n) · adventurous (a)","spoken":"adventure , adventurous","ipa":"adventure /æˈdvɛntʃɚ/ · adventurous /æˈdvɛntʃɚəs/","type":"noun · adjective · word family","meaning":"cuộc phiêu lưu · thích phiêu lưu/mạo hiểm","definition":"The encountering of risks; a bold undertaking, in which dangers are likely to be encountered, and the issue is staked upon unforeseen events; a daring feat.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The long journey across the desert became an unforgettable adventure."},{"number":21,"term":"keep (v) + V-ing","spoken":"keep + doing","ipa":"keep /kiːp/","type":"verb · phrase / pattern","meaning":"tiếp tục làm gì…","definition":"To continue doing an action or activity.","note":"keep/stay in touch thường gợi duy trì quan hệ; be in contact with trung tính và trang trọng hơn.","example":"The travellers kept walking until they reached a safe place."},{"number":22,"term":"decide (v) to V · decide (v) on st · decision (n) · make a decision","spoken":"decide to verb , decide on something , decision , make a decision","ipa":"decide /ˌdɪˈsaɪd/ · decision /dɪˈsɪʒən/ · make /meɪk/","type":"verb · noun · phrase / pattern · word family","meaning":"quyết định làm gì · lựa chọn sau khi cân nhắc · quyết định/sự lựa chọn · đưa ra quyết định","definition":"To choose an action; a choice that has been made.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"We decided to wait, and that decision saved money."},{"number":23,"term":"goal (n)","spoken":"goal","ipa":"goal /ɡoʊl/","type":"noun","meaning":"mục tiêu, mục đích","definition":"An aim; to work towards or reach an aim.","note":"","example":"Lan set a goal, pursued the goal every day, and finally achieved it."},{"number":24,"term":"journey (n)","spoken":"journey","ipa":"journey /ˈdʒɝːni/","type":"noun","meaning":"cuộc hành trình","definition":"The act of travelling from one place to another.","note":"","example":"The train journey took three hours."},{"number":25,"term":"set off (phrasal verb)","spoken":"set off","ipa":"set /sɛt/ · off /ɔːf/","type":"phrasal verb","meaning":"khởi hành","definition":"To begin a journey.","note":"set off: khởi hành; set off for + địa điểm.","example":"The group set off for the mountain village before sunrise."},{"number":26,"term":"route (n)","spoken":"route","ipa":"route /ruːt/","type":"noun","meaning":"tuyến đường","definition":"A course or way which is traveled or passed.","note":"","example":"The guide chose a safer route through the mountains after the heavy rain."},{"number":27,"term":"ancient (a)","spoken":"ancient","ipa":"ancient /ˈeɪntʃənt/","type":"adjective","meaning":"cổ đại","definition":"Belonging to a very distant period in history.","note":"","example":"The museum protects an ancient bowl that is over one thousand years old."},{"number":28,"term":"ruin (v) · ruin (n)","spoken":"ruin , ruin","ipa":"ruin /ˈruːən/","type":"verb · noun · word family","meaning":"phá hủy/làm hỏng · tàn tích","definition":"To damage something so badly that it loses its value or usefulness; as a noun, the remains of a destroyed building.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The storm ruined part of the ancient temple, but visitors can still explore the ruins."},{"number":29,"term":"flexible (a) · flexibility (n)","spoken":"flexible , flexibility","ipa":"flexible /ˈflɛksəbəl/ · flexibility /ˌflɛksəˈbɪləti/","type":"noun · adjective · word family","meaning":"linh hoạt · tính linh hoạt","definition":"Able to change or adapt easily; flexibility is the ability to do this.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A flexible schedule gave the team enough flexibility to avoid the storm."},{"number":30,"term":"polite (a) >< impolite (a) ~ rude (a)","spoken":"polite , impolite , rude","ipa":"polite /pəˈlaɪt/ · impolite /ˌɪmpəˈlaɪt/ · rude /ruːd/","type":"adjective · word family","meaning":"lịch sự >< bất lịch sự ~ thô lỗ","definition":"Well-mannered, civilized.","note":"impolite là không lịch sự; rude mạnh hơn, mang nghĩa thô lỗ.","example":"It's not polite to use a mobile phone in a restaurant."},{"number":31,"term":"cheat (v)","spoken":"cheat","ipa":"cheat /tʃiːt/","type":"verb","meaning":"gian lận, lừa đảo","definition":"To break rules in order to gain an unfair advantage.","note":"","example":"Players must not cheat because fair play is more important than winning."},{"number":32,"term":"rob (v)","spoken":"rob","ipa":"rob /rɑːb/","type":"verb","meaning":"cướp","definition":"To steal from a person or place; the crime of stealing.","note":"","example":"A thief robbed the shop, and a camera recorded the robbery."},{"number":33,"term":"cruise (n)","spoken":"cruise","ipa":"cruise /kruːz/","type":"noun","meaning":"chuyến du lịch bằng đường biển","definition":"A holiday journey by ship.","note":"","example":"The family went on a short cruise around the bay."},{"number":34,"term":"port (n)","spoken":"port","ipa":"port /pɔːrt/","type":"noun","meaning":"bến cảng","definition":"A place on the coast at which ships can shelter, or dock to load and unload cargo or passengers.","note":"","example":"The cruise ship remained in the port until the weather improved."},{"number":35,"term":"baggage (n)","spoken":"baggage","ipa":"baggage /ˈbæɡədʒ/","type":"noun","meaning":"túi xách nói chung, hành lí","definition":"(Usually uncountable) Luggage; traveling equipment.","note":"","example":"Passengers must collect their baggage before leaving the airport."},{"number":36,"term":"active (a) · active volcano","spoken":"active , active volcano","ipa":"active /ˈæktɪv/ · volcano /vɑˈlkeɪnoʊ/","type":"adjective · word family","meaning":"năng động/đang hoạt động · núi lửa đang hoạt động","definition":"Active describes something currently working or happening; an active volcano can erupt.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The active volcano is monitored closely because it may erupt again."},{"number":37,"term":"erupt (v) · eruption (n)","spoken":"erupt , eruption","ipa":"erupt /ɪˈrʌpt/ · eruption /ˌiˈrʌpʃən/","type":"verb · noun · word family","meaning":"phun trào · sự/vụ phun trào","definition":"To eject something violently (such as lava or water, as from a volcano or geyser).","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The active volcano erupted at night, and the eruption covered nearby roads with ash."},{"number":38,"term":"almost","spoken":"almost","ipa":"almost /ˈɔːˌlmoʊst/","type":"word / phrase","meaning":"gần như, hầu như","definition":"Not completely, but very nearly.","note":"almost + động từ/tính từ/số lượng; không dùng almost of.","example":"The travellers had almost reached the port when the storm began."},{"number":39,"term":"century (n) · decade (n) · millennium (n)","spoken":"century , decade , millennium","ipa":"century /ˈsɛntʃɚi/ · decade /dɛˈkeɪd/ · millennium /məˈlɛniəm/","type":"noun · word family","meaning":"thế kỉ · thập kỉ · thiên niên kỉ","definition":"A century is 100 years, a decade is 10 years, and a millennium is 1,000 years.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A century is ten decades, while a millennium is ten centuries."},{"number":40,"term":"recent (a) · recently (adv)","spoken":"recent , recently","ipa":"recent /ˈriːsənt/ · recently /ˈriːsəntli/","type":"adjective · adverb · word family","meaning":"gần đây/mới xảy ra · gần đây","definition":"Recent means happening or beginning not long ago; recently is the adverb.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A recent survey found that adventure tourism has grown rapidly in the region."},{"number":41,"term":"extreme sports","spoken":"extreme sports","ipa":"extreme /ɛˈkstriːm/ · sports /spɔːrts/","type":"word / phrase","meaning":"thể thao mạo hiểm","definition":"Sports involving speed, height, danger, or demanding physical conditions.","note":"","example":"Rock climbing and white-water rafting are popular extreme sports."},{"number":42,"term":"familiar (a) with sb/st","spoken":"familiar with somebody or something","ipa":"familiar /fəˈmɪljɚ/","type":"adjective · phrase / pattern","meaning":"quen thuộc với…","definition":"Well known to someone through experience.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: familiar (a) with sb/st","example":"Students should become familiar with the rules before the activity."},{"number":43,"term":"brave (a) · bravery (n)","spoken":"brave , bravery","ipa":"brave /breɪv/ · bravery /ˈbreɪvɚi/","type":"noun · adjective · word family","meaning":"dũng cảm · lòng dũng cảm","definition":"Showing courage; the quality of being courageous.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Nam was brave enough to speak first, and his bravery helped the group feel calm."},{"number":44,"term":"tourist attraction","spoken":"tourist attraction","ipa":"tourist /ˈtʊrəst/ · attraction /əˈtrækʃən/","type":"word / phrase","meaning":"điểm thu hút du lịch","definition":"A place or feature that visitors travel to see.","note":"","example":"The ancient temple is the region's most visited tourist attraction."},{"number":45,"term":"surf (v) · dive (v)","spoken":"surf , dive","ipa":"surf /sɝːf/ · dive /daɪv/","type":"verb · word family","meaning":"lướt sóng · lặn","definition":"To ride ocean waves on a board; to swim underwater, often using special equipment.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Visitors can surf near the beach or dive around the coral reef."},{"number":46,"term":"origin (n) · original (a)","spoken":"origin , original","ipa":"origin /ˈɔːrədʒən/ · original /ɚˈɪdʒənəl/","type":"noun · adjective · word family","meaning":"nguồn gốc · nguyên bản/độc đáo","definition":"Origin is where something begins or comes from; original means first or not copied.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The guide explained the origin of the tradition and showed us the original building."},{"number":47,"term":"state (v) · statement (n)","spoken":"state , statement","ipa":"state /steɪt/ · statement /ˈsteɪtmənt/","type":"verb · noun · word family","meaning":"nêu/tuyên bố · lời tuyên bố/phát biểu","definition":"To express something formally or clearly; a statement is what is said or written.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The travel company stated that the route was safe, but its statement was later questioned."},{"number":48,"term":"eventual (a)","spoken":"eventual","ipa":"eventual /əˈvɛntʃuəl/","type":"adjective","meaning":"rốt cuộc thì…; cuối cùng thì…","definition":"Happening at the end of a process or period of time.","note":"","example":"The eventual decision was delayed until the weather report arrived."},{"number":49,"term":"likely (a,adv) ~ possible (a)","spoken":"likely , possible","ipa":"likely /ˈlaɪkli/ · possible /ˈpɑːsəbəl/","type":"adjective · adverb · word family","meaning":"có khả năng cao ~ có thể xảy ra","definition":"Expected or possible to happen; likelihood is the degree of probability.","note":"likely thường dùng trong be likely to/It is likely that; possible mô tả khả năng có thể xảy ra nhưng không trực tiếp chỉ xác suất cao.","example":"Heavy rain is likely tonight, but flooding is only possible in low-lying areas."}],"pronunciationFocus":[{"entryNumber":20,"points":[{"category":"word-stress","note":"adventure và adventurous đều nhấn trọng âm chính ở âm tiết thứ hai"}]},{"entryNumber":25,"points":[{"category":"linking","note":"set‿off: nối /t/ cuối set với nguyên âm /ɔː/ đầu off"}]},{"entryNumber":37,"points":[{"category":"final-sound","note":"erupt /ɪˈrʌpt/: giữ đủ cụm /pt/ ở cuối"}]},{"entryNumber":39,"points":[{"category":"word-stress","note":"century nhấn âm đầu; decade và millennium nhấn âm thứ hai"}]},{"entryNumber":41,"points":[{"category":"final-sound","note":"sports /spɔːrts/: không bỏ /t/ trong cụm âm cuối /rts/"}]}]}};
